class NativeValueDecodeAdmissionTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void admittedTemporaryDoesNotReplaceTheStoresColdCanonicalModel(@TempDir Path directory) throws Exception {
		ValueStore store = new ValueStore(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(false));
		try {
			store.startTransaction(true);
			long id = store.storeValue(VF.createLiteral("payload".repeat(4096)));
			store.commit();
			store.clearCaches();
			LmdbValue original = store.getLazyValue(id);
			LmdbValue temporary = new LmdbLiteral(original.getValueStoreRevision(), id);
			assertThat(ValueStore.initializeAdmittedValue(temporary, ignored -> {
			})).isTrue();
			assertThat(original.isInitialized()).isFalse();
			assertThat(store.getLazyValue(id)).as("query-local decode must not publish into the store cache")
					.isSameAs(original);
		} finally {
			store.close();
		}
	}

	@Test
	void admittedTemporaryDoesNotPopulateTheStoresNamespaceCache(@TempDir Path directory) throws Exception {
		CountingValueStore store = new CountingValueStore(directory);
		try {
			String namespace = "urn:" + "namespace".repeat(4096) + "/";
			store.startTransaction(true);
			long first = store.storeValue(VF.createIRI(namespace + "first"));
			long second = store.storeValue(VF.createIRI(namespace + "second"));
			store.commit();
			store.clearCaches();
			LmdbValue original = store.getLazyValue(first);
			LmdbValue temporary = new LmdbIRI(original.getValueStoreRevision(), first);
			assertThat(ValueStore.initializeAdmittedValue(temporary, ignored -> {
			})).isTrue();
			LmdbValue later = store.getLazyValue(second);
			store.wholeRecordReads = 0;
			later.init();
			assertThat(store.wholeRecordReads).as("ordinary decode must still read the uncached namespace")
					.isGreaterThanOrEqualTo(2);
		} finally {
			store.close();
		}
	}

	@Test
	void snapshotAndPositionedSnapshotUseTheirOwnAdmittedRecord(@TempDir Path directory) throws Exception {
		ValueStore store = new ValueStore(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(false));
		try {
			String label = "snapshot-".repeat(16 * 1024);
			store.startTransaction(true);
			long id = store.storeValue(VF.createLiteral(label));
			store.commit();
			try (var reservation = store.reserveReadSnapshot(); var snapshot = reservation.start()) {
				LmdbValue first = store.getLazyValue(snapshot, id);
				LmdbValue positioned = store.getLazyValue(snapshot, id, ValuePosition.OBJECT);
				assertThat(first.isInitialized()).isFalse();
				assertThat(positioned.isInitialized()).isFalse();
				// Advance the current dictionary view while both values retain the older direct snapshot.
				store.startTransaction(true);
				store.storeValue(VF.createLiteral("current-view"));
				store.commit();
				assertRefusedWithoutInitialization(first);
				assertRefusedWithoutInitialization(positioned);
				AtomicLong admitted = new AtomicLong();
				assertThat(ValueStore.initializeAdmittedValue(first, admitted::addAndGet)).isTrue();
				assertThat(first.stringValue()).isEqualTo(label);
				assertThat(admitted.get()).isGreaterThan(label.length() * 8L);
				assertThat(ValueStore.initializeAdmittedValue(positioned, ignored -> {
				})).isTrue();
				assertThat(positioned.stringValue()).isEqualTo(label);
			}
		} finally {
			store.close();
		}
	}

	@Test
	void coveredOverlayIsSizedBeforeAnyWholeRecordReconstruction(@TempDir Path directory) throws Exception {
		CountingValueStore store = new CountingValueStore(directory);
		try {
			String label = "overlay-".repeat(16 * 1024);
			store.startTransaction(true);
			long id = store.storeValue(VF.createLiteral(label));
			store.commit();
			assertThat(store.warmCompressedValueOverlay(new CompressedValueOverlay.Options(
					32L << 20, 8192, 16, 1 << 20, 1 << 20, true, true))).isNotNull();
			boolean covered = store.withData(id, (address, length) -> false, record -> true);
			assertThat(covered).isTrue();
			store.clearCaches();
			LmdbValue cold = store.getLazyValue(id);
			assertThat(cold.isInitialized()).isFalse();
			store.wholeRecordReads = 0;
			assertRefusedWithoutInitialization(cold);
			assertThat(store.wholeRecordReads).as("refusal must precede getData's record byte array").isZero();
			assertThat(ValueStore.initializeAdmittedValue(cold, ignored -> {
			})).isTrue();
			assertThat(cold.stringValue()).isEqualTo(label);
			assertThat(store.wholeRecordReads).isPositive();
		} finally {
			store.close();
		}
	}

	@Test
	void releasedSnapshotDoesNotBorrowTheCurrentDictionary(@TempDir Path directory) throws Exception {
		ValueStore store = new ValueStore(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(false));
		try {
			store.startTransaction(true);
			long id = store.storeValue(VF.createLiteral("original"));
			store.commit();
			ValueStoreRevision revision;
			try (var reservation = store.reserveReadSnapshot(); var snapshot = reservation.start()) {
				revision = snapshot.revision();
			}
			LmdbValue cold = new LmdbLiteral(revision, id);
			assertThatThrownBy(() -> ValueStore.initializeAdmittedValue(cold, ignored -> {
			}))
					.isInstanceOf(SailException.class)
					.hasMessageContaining("snapshot is closed");
			assertThat(cold.isInitialized()).isFalse();
		} finally {
			store.close();
		}
	}

	private static void assertRefusedWithoutInitialization(LmdbValue value) {
		AtomicLong admitted = new AtomicLong();
		assertThatThrownBy(() -> ValueStore.initializeAdmittedValue(value, bytes -> {
			if (bytes > (64L << 10) - admitted.get()) {
				throw new QueryEvaluationException("test query memory admission refused");
			}
			admitted.addAndGet(bytes);
		})).isInstanceOf(QueryEvaluationException.class).hasMessageContaining("query memory admission");
		assertThat(value.isInitialized()).isFalse();
	}

	private static final class CountingValueStore extends ValueStore {
		int wholeRecordReads;

		CountingValueStore(Path directory) throws IOException {
			super(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(false).setValueOverlayEnabled(true));
		}

		@Override
		protected byte[] getData(long id) throws IOException {
			wholeRecordReads++;
			return super.getData(id);
		}
	}
}
